def limites_teste_binomial(n, p, nivel):
            moda = int(np.floor((n + 1) * p))
            def aceita(k):
                return binomtest(int(k), n, float(p), alternative='two-sided').pvalue >= nivel
            lo, hi = 0, moda
            while lo < hi:
                mid = (lo + hi) // 2
                if aceita(mid):
                    hi = mid
                else:
                    lo = mid + 1
            inferior = lo

            lo, hi = moda, n
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if aceita(mid):
                    lo = mid
                else:
                    hi = mid - 1
            superior = lo
            return inferior, superior
